window.FM_DATA["rendering"] = {"id":"rendering","title":"Rendering & Shaders","entries":[{"id":"fake-light","name":"FakeLight","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/FakeLight/FakeLight.cs","src_lines":[32,425],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/Fake Light"},"src_typeComment":"","src_serialized":[{"name":"lightColor","type":"Color","default":"new Color(1f, 0.7f, 0.35f)","tooltip":null,"header":"Common","range":null,"order":0,"comment":null},{"name":"intensity","type":"float","default":"1f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"lightType","type":"FakeLightType","default":"FakeLightType.Point","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"spotAngle","type":"float","default":"45f","tooltip":"Full cone angle in degrees (like Unity's real Light.spotAngle). Only used when Type is Spot.","header":null,"range":"1f, 179f","order":3,"comment":null},{"name":"enableSprite","type":"bool","default":"true","tooltip":null,"header":"Sprite — the light source's own look","range":null,"order":4,"comment":null},{"name":"spriteSize","type":"float","default":"0.5f","tooltip":null,"header":null,"range":null,"order":5,"comment":null},{"name":"glowSprite","type":"Sprite","default":null,"tooltip":"Leave empty to auto-generate a soft radial glow texture.","header":null,"range":null,"order":6,"comment":null},{"name":"enableBeam","type":"bool","default":null,"tooltip":null,"header":"Beam — a visible glowing cone (Spot type only)","range":null,"order":7,"comment":null},{"name":"beamLength","type":"float","default":"5f","tooltip":null,"header":null,"range":null,"order":8,"comment":null},{"name":"beamColor","type":"Color","default":"new Color(1f, 0.9f, 0.6f)","tooltip":null,"header":null,"range":null,"order":9,"comment":null},{"name":"beamIntensity","type":"float","default":"1f","tooltip":null,"header":null,"range":"0f, 5f","order":10,"comment":null},{"name":"enableInfluence","type":"bool","default":null,"tooltip":null,"header":"Influence — tints nearby geometry; works with or without the sprite","range":null,"order":11,"comment":null},{"name":"influenceMode","type":"FakeLightInfluenceMode","default":"FakeLightInfluenceMode.UniformTint","tooltip":"UniformTint (default): a single flat colour swap for the WHOLE renderer via MaterialPropertyBlock — zero setup, works on ANY material, but a large surface tints uniformly regardless of where on it the light is actually nearest.\n\nPerPixel: real per-fragment falloff via a shared global array (see FakeLightInclude.cginc) — only the geometry actually near the light is affected, like a real point light. Requires the material's shader to sample SampleFakeLights() (Toolkit/FakeLight/PerPixelReceiver already does).","header":null,"range":null,"order":12,"comment":null},{"name":"influenceRadius","type":"float","default":"4f","tooltip":null,"header":null,"range":null,"order":13,"comment":null},{"name":"influenceMask","type":"LayerMask","default":"~0","tooltip":null,"header":null,"range":null,"order":14,"comment":null},{"name":"influenceRescanInterval","type":"float","default":"0.5f","tooltip":"How often UniformTint mode re-scans for nearby renderers, in seconds — every-frame OverlapSphere is wasted work for a source that rarely moves. Not used in PerPixel mode.","header":null,"range":null,"order":15,"comment":null}],"src_members":[{"id":"MaxPerPixelLights","sig":"public const int MaxPerPixelLights = 8; // must match TOOLKIT_MAX_FAKE_LIGHTS in FakeLightInclude.cginc","kind":"const","name":"MaxPerPixelLights","static":false,"comment":null},{"id":"PublishPerPixelLights()","sig":"public static void PublishPerPixelLights()","kind":"method","name":"PublishPerPixelLights","static":true,"comment":"Public — not gated behind Update() — so a self-test can drive this deterministically without waiting on a real frame, same reasoning as every other \"public Tick-equivalent\" in this toolkit."},{"id":"ComputeSpotAttenuation(Vector3, Vector3, float)","sig":"public static float ComputeSpotAttenuation(Vector3 toPixelDirection, Vector3 lightForward, float cosHalfAngle)","kind":"method","name":"ComputeSpotAttenuation","static":true,"comment":"Pure — mirrors FakeLightInclude.cginc's SampleFakeLights spot-angle math exactly, so a self-test can assert the CPU and shader sides agree without needing to read GPU state back."},{"id":"ActivePerPixelLightCountForTest","sig":"public static int ActivePerPixelLightCountForTest => ActivePerPixelLights.Count","kind":"property","name":"ActivePerPixelLightCountForTest","static":true,"comment":"Test-only accessors — reading GLOBAL shader state back isn't otherwise observable from a script in a way a self-test can assert against."},{"id":"PublishedPerPixelPositionSlotForTest(int)","sig":"public static Vector4 PublishedPerPixelPositionSlotForTest(int index) => PerPixelPositionsBuffer[index]","kind":"method","name":"PublishedPerPixelPositionSlotForTest","static":true,"comment":null},{"id":"PublishedPerPixelColorSlotForTest(int)","sig":"public static Vector4 PublishedPerPixelColorSlotForTest(int index) => PerPixelColorsBuffer[index]","kind":"method","name":"PublishedPerPixelColorSlotForTest","static":true,"comment":null},{"id":"PublishedPerPixelSpotParamsSlotForTest(int)","sig":"public static Vector4 PublishedPerPixelSpotParamsSlotForTest(int index) => PerPixelSpotParamsBuffer[index]","kind":"method","name":"PublishedPerPixelSpotParamsSlotForTest","static":true,"comment":null},{"id":"ResetPerPixelPublishGuardForTest()","sig":"public static void ResetPerPixelPublishGuardForTest() => lastPublishedFrame = -1","kind":"method","name":"ResetPerPixelPublishGuardForTest","static":true,"comment":null},{"id":"RescanAndApplyInfluence()","sig":"public void RescanAndApplyInfluence()","kind":"method","name":"RescanAndApplyInfluence","static":false,"comment":"Public — not gated behind the rescan timer — so a self-test (or a caller that just moved the light) can drive this deterministically instead of waiting on real elapsed time."},{"id":"GenerateConeMesh(float, float, int)","sig":"public static Mesh GenerateConeMesh(float length, float angleDegrees, int segments = 20)","kind":"method","name":"GenerateConeMesh","static":true,"comment":"A cone mesh — apex at the origin (the light's own position), opening along LOCAL +Z (the light's forward direction) out to beamLength, with a radius set by the spot angle. Vertex colour alpha is 1 at the apex and 0 around the rim, so ordinary alpha interpolation across each triangle gives the whole cone a bright-near-the-source, fading-toward-the-edge gradient for free — no texture needed."}],"src_enumValues":[],"src_selfTest":"Rendering/FakeLight/Editor/FakeLightSelfTest.cs","src_demoScene":["FakeLight_Demo"],"entryKind":"tool","status":"published","summary":"A light-looking effect with no real Light: a glow sprite, a beam, and tinting of nearby renderers.","overview":["A stand-in for a real Light where a full Light component's cost is not wanted — Built-in RP has no cheap built-in \"fake light\". Three independent parts, each switchable: a glow sprite, a volumetric-looking beam, and influence, which actually affects nearby geometry."],"features":[{"name":"Sprite","what":"a soft radial glow billboard. Auto-generated if you assign no texture."},{"name":"Beam","what":"a cone of light for a torch or spotlight look."},{"name":"Influence","what":"tints nearby renderers so the light appears to affect the world."}],"useCases":["Dozens of torches or lamps where real lights would cost too much.","A stylised glow that does not need to obey real lighting.","Mobile or low-end targets where per-pixel lights are scarce."],"params":[{"field":"influenceMode","tuning":"UniformTint works on ANY material with zero setup but tints a whole renderer evenly, which shows on large surfaces. PerPixel gives real falloff but requires the material's shader to sample the toolkit's include."},{"field":"influenceRescanInterval","tuning":"UniformTint only. Re-scanning every frame is wasted work for a light that never moves — raise it for static lamps."},{"field":"spotAngle","tuning":"The FULL cone angle, matching Unity's own Light.spotAngle. Only used in Spot mode."},{"field":"glowSprite","tuning":"Leave empty and it generates a soft radial texture, which is usually better than a hand-made one."}],"gotchas":[{"title":"PerPixel needs a cooperating shader","body":"The material must sample the FakeLight include. On a standard material, PerPixel simply does nothing — which reads as the light being broken."},{"title":"There is a hard limit on per-pixel lights","body":"They publish into a fixed-size global array. Beyond the limit, extra lights are dropped rather than queued."}],"seeAlso":["UIFakeLight","SceneLightUIHook"],"src_uses":["FakeLightInfluenceMode","FakeLightType","GrassBendEmitter","MaterialPropertyBlockHelper","RippleEmitter"],"src_usedBy":["EdgeGlowPattern","EdgeGlowShape","FakeLightInfluenceMode","FakeLightType","MaterialPropertyBlockHelper","UIEdgeGlow","UIFakeLight","UIFakeLightType"],"src_extensionPoints":[],"parts":[{"id":"fake-light-influence-mode","name":"FakeLightInfluenceMode","cat":"Rendering","src_typeKind":"enum","src_ns":"Toolkit.Rendering","src_file":"Rendering/FakeLight/FakeLight.cs","src_lines":[24,24],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"A stand-in for a real Light where a full Light component's cost isn't wanted — Built-in RP has no cheap built-in \"fake point light\" of its own. Two independent, combinable behaviours (as scoped: \"explore light influence\" alongside the sprite, not instead of it): - Sprite: a camera-facing glow quad at this position, so the LIGHT SOURCE ITSELF reads as lit (a torch flame, a magic orb) without a real Light casting anything. - Influence: tints nearby real renderers' ALBEDO (not emission — see note below) toward this light's colour, falling off with distance, so SURROUNDING geometry also reads as lit. This is the part the sprite alone can't do.  Why albedo (_Color) and not _EmissionColor for influence: emission only renders if the target material already has the _EMISSION keyword + non-black GI flags enabled, which most materials don't by default — that would make the effect SILENTLY do nothing on an unprepared material, exactly the class of bug this toolkit's self-tests exist to catch. Tinting _Color works on any Standard-shader material with zero setup.  KNOWN LIMITATION, accepted rather than solved: if two FakeLights' influence radii overlap the same renderer, whichever rescans last wins — there's no central accumulator blending multiple lights' contributions together. A real multi-light accumulation system is a much bigger tool than this. UniformTint vs PerPixel — see the Influence header's tooltip for the tradeoff.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"A stand-in for a real Light where a full Light component's cost isn't wanted — Built-in RP has no cheap built-in \"fake...","src_uses":["FakeLight","FakeLightType","GrassBendEmitter","MaterialPropertyBlockHelper","RippleEmitter"],"src_usedBy":["FakeLight","FakeLightType"],"src_extensionPoints":[],"foldedInto":"fake-light"},{"id":"fake-light-type","name":"FakeLightType","cat":"Rendering","src_typeKind":"enum","src_ns":"Toolkit.Rendering","src_file":"Rendering/FakeLight/FakeLight.cs","src_lines":[29,29],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Point: omnidirectional, falls off with distance only (the original behaviour). Spot: also restricted to a cone along the light's own forward direction — both the influence (per-pixel or uniform) AND the optional visible Beam mesh respect this.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"Point: omnidirectional, falls off with distance only (the original behaviour).","src_uses":["FakeLight","FakeLightInfluenceMode","GrassBendEmitter","MaterialPropertyBlockHelper","RippleEmitter"],"src_usedBy":["FakeLight","FakeLightInfluenceMode"],"src_extensionPoints":[],"foldedInto":"fake-light"}]},{"id":"ui-fake-light","name":"UIFakeLight","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/FakeLightOverlay/UIFakeLight.cs","src_lines":[18,120],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/UI Fake Light (Overlay)"},"src_typeComment":"The Screen Space Overlay equivalent of FakeLight's PerPixel mode — a SEPARATE tool, not a variant of the 3D FakeLight, because overlay UI has no 3D world position at all to sample. Publishes real SCREEN-PIXEL coordinates into a shared global array every frame (same \"global array\" technique as FakeLight/ GrassBendEmitter/RippleEmitter), sampled by Toolkit/UI/Fake Light Receiver via UIFakeLightOverlayInclude.cginc's SampleUIFakeLights(). Point and Spot both supported.  Place this on a RectTransform under a Screen Space - Overlay canvas — its own .position IS the real screen-pixel position for that render mode (Unity's own convention, the same one RectTransformUtility.WorldToScreenPoint relies on), so no camera/projection math is needed here.","src_serialized":[{"name":"lightColor","type":"Color","default":"new Color(1f, 0.9f, 0.6f)","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"intensity","type":"float","default":"1f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"radius","type":"float","default":"200f","tooltip":"In pixels.","header":null,"range":null,"order":2,"comment":null},{"name":"lightType","type":"UIFakeLightType","default":"UIFakeLightType.Point","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"spotAngle","type":"float","default":"60f","tooltip":"Full cone angle in degrees. Only used when Type is Spot. The cone points along this RectTransform's local +X axis — rotate the RectTransform (its Z rotation) to aim it.","header":null,"range":"1f, 179f","order":4,"comment":null}],"src_members":[{"id":"MaxLights","sig":"public const int MaxLights = 8; // must match TOOLKIT_MAX_UI_FAKE_LIGHTS in UIFakeLightOverlayInclude.cginc","kind":"const","name":"MaxLights","static":false,"comment":null},{"id":"Publish()","sig":"public static void Publish()","kind":"method","name":"Publish","static":true,"comment":"Public — not gated behind Update() — so a self-test can drive this deterministically without waiting on a real frame."},{"id":"ActiveLightCountForTest","sig":"public static int ActiveLightCountForTest => ActiveLights.Count","kind":"property","name":"ActiveLightCountForTest","static":true,"comment":"Test-only accessors — reading GLOBAL shader state back isn't otherwise observable from a script in a way a self-test can assert against."},{"id":"PublishedPositionSlotForTest(int)","sig":"public static Vector4 PublishedPositionSlotForTest(int index) => PositionsBuffer[index]","kind":"method","name":"PublishedPositionSlotForTest","static":true,"comment":null},{"id":"PublishedColorSlotForTest(int)","sig":"public static Vector4 PublishedColorSlotForTest(int index) => ColorsBuffer[index]","kind":"method","name":"PublishedColorSlotForTest","static":true,"comment":null},{"id":"PublishedSpotParamsSlotForTest(int)","sig":"public static Vector4 PublishedSpotParamsSlotForTest(int index) => SpotParamsBuffer[index]","kind":"method","name":"PublishedSpotParamsSlotForTest","static":true,"comment":null},{"id":"ResetPublishGuardForTest()","sig":"public static void ResetPublishGuardForTest() => lastPublishedFrame = -1","kind":"method","name":"ResetPublishGuardForTest","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":"Rendering/UI/FakeLightOverlay/Editor/UIFakeLightSelfTest.cs","src_demoScene":["UIFakeLightOverlay_Demo"],"entryKind":"tool","status":"published","summary":"The Screen Space Overlay equivalent of FakeLight, working in screen pixels.","overview":["A separate tool rather than a mode of the 3D FakeLight, because overlay UI has no 3D world position to sample from at all. It publishes real SCREEN-PIXEL coordinates into a shared global array each frame, using the same technique the 3D version uses in world space."],"useCases":["A glow that appears to light UI panels and icons.","A torch or scanner effect over a menu.","Lighting flat UI without moving it into world space."],"params":[{"field":"radius","tuning":"In PIXELS, not world units — so the same value covers different amounts of UI at different resolutions."}],"gotchas":[{"title":"Overlay only","body":"A Screen Space Camera or World Space canvas has a real position, so the 3D FakeLight applies there instead. Mixing them up is the usual reason nothing lights."}],"seeAlso":["FakeLight","UILightingEffect"],"src_uses":["FakeLight","GrassBendEmitter","RippleEmitter","UIFakeLightType"],"src_usedBy":["UIFakeLightType"],"src_extensionPoints":[],"parts":[{"id":"ui-fake-light-type","name":"UIFakeLightType","cat":"Rendering","src_typeKind":"enum","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/FakeLightOverlay/UIFakeLight.cs","src_lines":[6,6],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["FakeLight","GrassBendEmitter","RippleEmitter","UIFakeLight"],"src_usedBy":["UIFakeLight"],"src_extensionPoints":[],"foldedInto":"ui-fake-light"}]},{"id":"scene-light-ui-hook","name":"SceneLightUIHook","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/LightingEffects/SceneLightUIHook.cs","src_lines":[11,47],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/Scene Light UI Hook"},"src_typeComment":"Drop ANYWHERE in the scene (once) to publish the scene's main Directional Light's direction as a GLOBAL shader value, which Toolkit/UI/Lighting Effects' Scene Light mode reads to fake-light UI elements as if they were flat cards facing the camera. Without this, Scene Light mode's light direction defaults to zero, which reads as flat/shadowed everywhere — not an error, just nothing to react to.","src_serialized":[{"name":"directionalLight","type":"Light","default":null,"tooltip":"Leave empty to auto-find the first enabled Directional Light in the scene.","header":null,"range":null,"order":0,"comment":null},{"name":"updateEveryFrame","type":"bool","default":"true","tooltip":"Turn off if the light never rotates at runtime, to skip needless per-frame work.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"PublishDirection()","sig":"public void PublishDirection()","kind":"method","name":"PublishDirection","static":false,"comment":"Public so a self-test (or a script that just changed which light is assigned) can push an update without waiting for the next Update tick."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UILightingEffects_Demo"],"entryKind":"tool","status":"published","summary":"Publishes the scene's main directional light direction as a global shader value, for UI lighting.","overview":["Drop it anywhere in the scene, once. It publishes the main Directional Light's direction globally, which the UI lighting effect's Scene Light mode reads to shade UI as if it were flat cards facing the camera. Without it, that mode falls back to a default direction."],"useCases":["UI that visually agrees with the scene's time of day.","Inventory cards catching the same light as the world.","A day-night cycle whose direction reaches the UI."],"params":[{"field":"directionalLight","tuning":"Leave empty to auto-find the first enabled directional light, which is right in most scenes and wrong in one with several."},{"field":"updateEveryFrame","tuning":"Turn off when the light never rotates, to skip the per-frame publish entirely."}],"gotchas":[{"title":"Once per scene, not once per element","body":"It publishes a global value. A second one just overwrites the first."}],"seeAlso":["UILightingEffect","FakeLight"],"src_uses":[],"src_usedBy":["UILightingEffect","UILightingMode"],"src_extensionPoints":[]},{"id":"ui-lighting-effect","name":"UILightingEffect","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/LightingEffects/UILightingEffect.cs","src_lines":[15,119],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Graphic)"],"addComponentMenu":"Toolkit/Rendering/UI Lighting Effect"},"src_typeComment":"Drop on any UI Graphic (Image, RawImage, ...) and pick a Mode from the dropdown — a sweeping shine highlight, a rim/edge glow, or normal-mapped shading reactive to the scene's real light direction (see SceneLightUIHook.cs). One shared shader (Toolkit/UI/Lighting Effects) implements all three; this component just creates a private material instance for the Graphic and pushes the chosen mode's settings into it.","src_serialized":[{"name":"mode","type":"UILightingMode","default":"UILightingMode.Shine","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"shineColor","type":"Color","default":"Color.white","tooltip":null,"header":"Shine","range":null,"order":1,"comment":null},{"name":"shineIntensity","type":"float","default":"1f","tooltip":null,"header":null,"range":"0f, 3f","order":2,"comment":null},{"name":"sweepSpeed","type":"float","default":"0.5f","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"sweepWidth","type":"float","default":"0.15f","tooltip":null,"header":null,"range":"0.02f, 1f","order":4,"comment":null},{"name":"sweepAngle","type":"float","default":"45f","tooltip":"Direction the sweep travels across the element. 45 matches the old fixed diagonal; 0/180 is horizontal, 90 is vertical.","header":null,"range":"0f, 180f","order":5,"comment":null},{"name":"sweepFrequency","type":"float","default":"1f","tooltip":"How many parallel bands sweep at once, tiled across the element. 1 = a single band (the old look, now with a softer falloff).","header":null,"range":"0.25f, 8f","order":6,"comment":null},{"name":"rimColor","type":"Color","default":"new Color(0.4f, 0.8f, 1f)","tooltip":null,"header":"Rim","range":null,"order":7,"comment":null},{"name":"rimIntensity","type":"float","default":"1f","tooltip":null,"header":null,"range":"0f, 3f","order":8,"comment":null},{"name":"rimWidth","type":"float","default":"0.1f","tooltip":null,"header":null,"range":"0.01f, 0.5f","order":9,"comment":null},{"name":"rimFalloff","type":"float","default":"1.5f","tooltip":null,"header":null,"range":"0.5f, 4f","order":10,"comment":null},{"name":"normalMap","type":"Texture","default":null,"tooltip":"Needs a real normal map to look like anything other than a flat tint shift — Properties defaults to Unity's built-in flat \"bump\" texture.","header":"Scene Light","range":null,"order":11,"comment":null},{"name":"litTint","type":"Color","default":"Color.white","tooltip":null,"header":null,"range":null,"order":12,"comment":null},{"name":"shadowTint","type":"Color","default":"new Color(0.3f, 0.3f, 0.35f)","tooltip":null,"header":null,"range":null,"order":13,"comment":null}],"src_members":[{"id":"MaterialInstance","sig":"public Material MaterialInstance => materialInstance","kind":"property","name":"MaterialInstance","static":false,"comment":null},{"id":"ApplySettings()","sig":"public void ApplySettings()","kind":"method","name":"ApplySettings","static":false,"comment":"Public so a self-test (or a runtime UI system swapping modes/colours) can push a settings change without waiting for OnValidate. The shine sweep itself animates purely via the shader's own _Time.y — this does NOT need to be called every frame, only when a setting actually changes."}],"src_enumValues":[],"src_selfTest":"Rendering/UI/LightingEffects/Editor/UILightingEffectSelfTest.cs","src_demoScene":["UILightingEffects_Demo"],"entryKind":"tool","status":"published","summary":"Three UI lighting looks in one component: sweeping shine, rim glow, and normal-mapped shading.","overview":["Drop it on any UI Graphic and pick a mode. One shared shader implements all three, so switching mode is a dropdown rather than a different material. Scene Light mode reacts to the real directional light, via the scene hook."],"useCases":["A shine sweeping across a button to draw attention.","A rim glow marking a selected or equipped item.","Normal-mapped UI that catches the scene's light."],"params":[{"field":"mode","tuning":"Shine, Rim and Scene Light are mutually exclusive. Most of the other settings only apply to one of them."},{"field":"sweepAngle","tuning":"45 matches the conventional diagonal shine. Zero sweeps horizontally, which reads as a scanline."},{"field":"normalMap","tuning":"Scene Light mode needs a real normal map to look like anything other than flat shading."}],"gotchas":[{"title":"Most settings are mode-specific","body":"Adjusting a rim setting in Shine mode changes nothing. Expected, and confusing in a long Inspector."},{"title":"Scene Light mode needs the hook in the scene","body":"Without SceneLightUIHook the direction is a default, so the shading will not match the world."}],"seeAlso":["SceneLightUIHook","UIEdgeGlow"],"src_uses":["SceneLightUIHook","UILightingMode"],"src_usedBy":["EdgeGlowPattern","EdgeGlowShape","UIEdgeGlow","UILightingMode"],"src_extensionPoints":[],"parts":[{"id":"ui-lighting-mode","name":"UILightingMode","cat":"Rendering","src_typeKind":"enum","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/LightingEffects/UILightingEffect.cs","src_lines":[6,6],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["SceneLightUIHook","UILightingEffect"],"src_usedBy":["UILightingEffect"],"src_extensionPoints":[],"foldedInto":"ui-lighting-effect"}]},{"id":"ripple-emitter","name":"RippleEmitter","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Water/Ripple/RippleEmitter.cs","src_lines":[13,99],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Rendering/Ripple Emitter"},"src_typeComment":"Drop this on ANY GameObject whose Renderer uses a shader that includes RippleInclude.cginc — every shader in Rendering/Water/ (Realistic, Stylized, 2D) already does. It drives the shared _RippleImpacts array via a MaterialPropertyBlock, so it never touches (or needs to know) which specific shader is assigned: dragging this same component onto a Stylized-water object instead of a Realistic-water one \"just works\", because the two shaders agree on the same property names rather than knowing about each other or about this component.","src_serialized":[{"name":"rippleSpeed","type":"float","default":"3f","tooltip":"World units/second the ring expands outward.","header":null,"range":null,"order":0,"comment":null},{"name":"rippleWidth","type":"float","default":"0.5f","tooltip":"Thickness of the expanding ring, in world units.","header":null,"range":null,"order":1,"comment":null},{"name":"rippleLifetime","type":"float","default":"2f","tooltip":"Seconds before a ripple fully fades out.","header":null,"range":null,"order":2,"comment":null},{"name":"rippleHeight","type":"float","default":"0.05f","tooltip":"Peak vertical displacement / normal-perturbation strength.","header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"ActiveImpactCount","sig":"public int ActiveImpactCount { get; private set; }","kind":"property","name":"ActiveImpactCount","static":false,"comment":null},{"id":"AddImpact(Vector3)","sig":"public void AddImpact(Vector3 worldPosition)","kind":"method","name":"AddImpact","static":false,"comment":"Call this from a footstep event, a rain droplet spawner, a TriggerEventRelay.OnEnter — anything that has a world position and a moment something touched the water. Impacts are stored in a ring buffer: once more than MaxRipples land within one lifetime, the OLDEST slot is silently reused rather than the array growing unbounded."}],"src_enumValues":[],"src_selfTest":"Rendering/Water/Ripple/Editor/RippleEmitterSelfTest.cs","src_demoScene":["Water_Demo"],"entryKind":"tool","status":"published","summary":"Drives the shared ripple array so any water shader reacts, without knowing which shader it is.","overview":["Drop it on any object whose Renderer uses a shader including the ripple include — every water shader in the toolkit already does. It drives the shared impacts array through a MaterialPropertyBlock, so it never needs to know which specific water shader is on the surface."],"useCases":["Footsteps or raindrops disturbing water.","Impact ripples where something enters the water.","Any surface shader that wants expanding rings."],"params":[{"field":"rippleLifetime","tuning":"Together with the array size this decides how many ripples can overlap before the oldest is replaced."},{"field":"rippleSpeed","tuning":"World units per second. Slow ripples on a large lake look right; the same value on a puddle looks frozen."}],"gotchas":[{"title":"The shader must include the ripple header","body":"On a material that does not, the emitter runs and nothing appears. That is the first thing to check."},{"title":"Impacts are a fixed-size array","body":"Beyond the limit, the oldest ripple is replaced. Rapid emission means short-lived ripples."}],"seeAlso":["WaterInstanceOverrides","UIRippleEffect","GrassBendEmitter"],"src_uses":["TriggerEventRelay","WaterInstanceOverrides"],"src_usedBy":["FakeLight","FakeLightInfluenceMode","FakeLightType","GrassBendEmitter","UIFakeLight","UIFakeLightType","WaterInstanceOverrides"],"src_extensionPoints":[]},{"id":"planar-reflection","name":"PlanarReflection","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Water/Reflection/PlanarReflection.cs","src_lines":[18,175],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Rendering/Planar Reflection"},"src_typeComment":"Real planar reflections for a flat water surface (mirrors, wet floors) — a second camera renders the scene MIRRORED across this object's own plane (transform.position/up) into a low-res RenderTexture, which the water shader then samples via screen-space UV (see PlanarReflectionInclude.cginc). This is the classic Built-in RP technique (the same one Unity's old \"Water\" Standard Asset used): compose the main camera's view matrix with a reflection matrix rather than deriving position/rotation separately, and use an OBLIQUE near-clip plane so geometry behind the water surface never appears in its own reflection.  Deliberately NOT GrabPass — this renders its OWN small, controlled RenderTexture once per frame (see [[unitytools-toolkit-conventions]] / the GrabPass explanation this was built alongside), not a full- screen copy for every reflective object.","src_serialized":[{"name":"reflectionMask","type":"LayerMask","default":"~0","tooltip":"What gets rendered INTO the reflection. Exclude UI, water itself, and anything expensive that wouldn't be missed at a glance.","header":null,"range":null,"order":0,"comment":null},{"name":"textureSize","type":"int","default":"512","tooltip":"Resolution of the reflection RenderTexture — the actual cost lever. Low is fine; a blurry/soft reflection reads as realistic anyway (real water is rarely a perfect mirror).","header":null,"range":null,"order":1,"comment":null},{"name":"clipPlaneOffset","type":"float","default":"0.07f","tooltip":"Pushes the clip plane very slightly along the surface normal, avoiding a thin sliver of self-intersection artifacts right at the water line.","header":null,"range":null,"order":2,"comment":null},{"name":"updateEveryNFrames","type":"int","default":"1","tooltip":"Re-renders the reflection every N frames instead of every frame — 1 = every frame (smoothest, priciest), higher trades smoothness for cost. Water rarely needs a perfectly current reflection.","header":null,"range":null,"order":3,"comment":null},{"name":"disablePixelLightsWhileRendering","type":"bool","default":"true","tooltip":"Temporarily drops the quality-settings pixel light count to 0 while rendering the reflection — a real, well-established cost cut for a scene reflection that doesn't need per-pixel lighting fidelity.","header":null,"range":null,"order":4,"comment":null}],"src_members":[{"id":"PlaneEquation(Vector3, Vector3, float, float)","sig":"public static Vector4 PlaneEquation(Vector3 position, Vector3 normal, float sideSign, float offset)","kind":"method","name":"PlaneEquation","static":true,"comment":"A plane through `position` with unit `normal`, expressed as (a, b, c, d) for ax+by+cz+d=0, nudged slightly along the normal by `offset` and flipped by `sideSign` (matches CameraSpacePlane's signature so both can build a consistent plane representation)."},{"id":"CameraSpacePlane(Camera, Vector3, Vector3, float, float)","sig":"public static Vector4 CameraSpacePlane(Camera camera, Vector3 position, Vector3 normal, float sideSign, float offset)","kind":"method","name":"CameraSpacePlane","static":true,"comment":"The same plane, but expressed in `camera`'s own view space — what Camera.CalculateObliqueMatrix needs to clip a projection to exactly that plane."},{"id":"CalculateReflectionMatrix(Vector4)","sig":"public static Matrix4x4 CalculateReflectionMatrix(Vector4 plane)","kind":"method","name":"CalculateReflectionMatrix","static":true,"comment":"The 4x4 matrix that reflects any world-space point/vector across the given plane. Composed with a camera's own worldToCameraMatrix (reflectionCamera.worldToCameraMatrix = source.worldToCameraMatrix * this), it turns that camera's view into the mirrored view a reflection needs — standard Householder reflection extended to a general plane via the plane's own (a,b,c,d) equation."}],"src_enumValues":[],"src_selfTest":"Rendering/Water/Reflection/Editor/PlanarReflectionSelfTest.cs","src_demoScene":["Water_Demo"],"entryKind":"tool","status":"published","summary":"Real mirrored reflections for a flat surface, rendered by a second camera into a low-res texture.","overview":["A second camera renders the scene mirrored across this object's plane into a low-resolution RenderTexture, which the water shader samples in screen space. Real reflections rather than a cubemap approximation, at the cost of a second render of the scene."],"useCases":["Water that genuinely reflects the level.","Mirrors and polished floors.","Wet surfaces in a scene where a cubemap would look obviously wrong."],"params":[{"field":"reflectionMask","tuning":"Exclude UI, the water itself, and anything that does not need reflecting. This is the main cost control — everything included is rendered a second time."},{"field":"textureSize","tuning":"Reflections tolerate low resolution remarkably well. Halving this is usually invisible and much cheaper."},{"field":"updateEveryNFrames","tuning":"Still water can update every few frames with nobody noticing."},{"field":"clipPlaneOffset","tuning":"Pushes the clip plane slightly along the normal to stop artefacts right at the waterline. Too much and objects float visibly above their reflection."}],"gotchas":[{"title":"It renders the scene twice","body":"That is the whole technique. The mask and the resolution are the levers — there is no way to make it free."},{"title":"It only works for a FLAT plane","body":"Planar means planar. A rippling surface still reflects as if flat, which is why the normal perturbation carries the illusion."}],"seeAlso":["WaterDepthTextureEnabler","WaterInstanceOverrides"],"src_uses":[],"src_usedBy":["WaterInstanceOverrides"],"src_extensionPoints":[]},{"id":"water-depth-texture-enabler","name":"WaterDepthTextureEnabler","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Water/WaterDepthTextureEnabler.cs","src_lines":[11,20],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/Water Depth Texture Enabler"},"src_typeComment":"Any water shader that samples _CameraDepthTexture for shoreline foam needs the CAMERA to actually generate that texture — Unity only does so when a camera's depthTextureMode requests it, and a shader has no way to request this on its own. Drop this on whatever camera will see the water (or call EnsureDepthTexture(camera) once from code) instead of remembering to flip the flag by hand — without it, shoreline foam silently reads as \"always deep water\" rather than erroring.","src_serialized":[],"src_members":[{"id":"EnsureDepthTexture(Camera)","sig":"public static void EnsureDepthTexture(Camera camera)","kind":"method","name":"EnsureDepthTexture","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["Water_Demo"],"entryKind":"tool","status":"published","summary":"Makes the camera generate the depth texture that shoreline foam needs.","overview":["A water shader sampling the camera depth texture for shoreline foam needs the CAMERA to actually generate it, and a shader cannot request that itself. Drop this on whatever camera sees the water."],"useCases":["Shoreline foam where water meets terrain.","Any depth-based water effect such as depth-tinted shallows.","Fixing foam that works in one scene and not another."],"gotchas":[{"title":"Missing it looks like a broken shader, not a missing setting","body":"Foam simply does not appear, with no error anywhere. If shoreline foam is absent, this is almost always the reason."}],"seeAlso":["PlanarReflection","WaterInstanceOverrides"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"water-instance-overrides","name":"WaterInstanceOverrides","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Water/WaterInstanceOverrides.cs","src_lines":[19,177],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Rendering/Water Instance Overrides"},"src_typeComment":"Drop on ANY water surface (Stylized, Realistic, or 2D) to override its visual settings on THIS INSTANCE only, without needing a separate Material asset — e.g. two ponds sharing one Realistic Water material, where one has gentler waves and a murkier tint than the other. Works via a MaterialPropertyBlock, same mechanism as RippleEmitter: writes properties by NAME, so it applies to whichever of the three water shaders is actually assigned, and never touches the shared Material — every OTHER object still using that Material is completely unaffected.  Each group below has its own enable toggle. OFF means \"inherit the Material's own value\" — genuinely inherit, not just \"leave alone\": since a MaterialPropertyBlock has no way to un-set a property once written, turning a group off makes this component copy the Material's CURRENT value for that group's properties into the block instead, which is visually indistinguishable from no override at all and never leaves stale data behind from a previous ON state.","src_serialized":[{"name":"overrideWaves","type":"bool","default":null,"tooltip":null,"header":"Waves - Realistic & Stylized only, no effect on 2D","range":null,"order":0,"comment":null},{"name":"waveADirection","type":"Vector2","default":"new Vector2(1f, 0.4f)","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"waveALength","type":"float","default":"6f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"waveASteepness","type":"float","default":"0.3f","tooltip":null,"header":null,"range":"0f, 0.8f","order":3,"comment":null},{"name":"waveASpeed","type":"float","default":"1.2f","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"waveBDirection","type":"Vector2","default":"new Vector2(0.3f, -1f)","tooltip":null,"header":null,"range":null,"order":5,"comment":null},{"name":"waveBLength","type":"float","default":"3.5f","tooltip":null,"header":null,"range":null,"order":6,"comment":null},{"name":"waveBSteepness","type":"float","default":"0.2f","tooltip":null,"header":null,"range":"0f, 0.8f","order":7,"comment":null},{"name":"waveBSpeed","type":"float","default":"0.9f","tooltip":null,"header":null,"range":null,"order":8,"comment":null},{"name":"overrideFoam","type":"bool","default":null,"tooltip":null,"header":"Foam","range":null,"order":9,"comment":null},{"name":"foamColor","type":"Color","default":"Color.white","tooltip":null,"header":null,"range":null,"order":10,"comment":null},{"name":"foamAmount","type":"float","default":"0.3f","tooltip":"Crest foam - Stylized only, no effect on Realistic/2D.","header":null,"range":"0f, 1f","order":11,"comment":null},{"name":"foamDistance","type":"float","default":"0.5f","tooltip":"Shoreline foam - all three shaders.","header":null,"range":"0.05f, 5f","order":12,"comment":null},{"name":"overrideColors","type":"bool","default":null,"tooltip":null,"header":"Colors","range":null,"order":13,"comment":null},{"name":"shallowColor","type":"Color","default":"new Color(0.15f, 0.5f, 0.55f, 0.7f)","tooltip":null,"header":null,"range":null,"order":14,"comment":null},{"name":"deepColor","type":"Color","default":"new Color(0f, 0.15f, 0.25f, 0.95f)","tooltip":null,"header":null,"range":null,"order":15,"comment":null},{"name":"overrideNormalFlow","type":"bool","default":null,"tooltip":null,"header":"Normal Map Flow - Realistic only, no effect on Stylized/2D","range":null,"order":16,"comment":null},{"name":"normalStrength","type":"float","default":"0.5f","tooltip":null,"header":null,"range":"0f, 2f","order":17,"comment":null},{"name":"normalScrollSpeed1","type":"Vector2","default":"new Vector2(0.05f, 0.03f)","tooltip":null,"header":null,"range":null,"order":18,"comment":null},{"name":"normalScrollSpeed2","type":"Vector2","default":"new Vector2(-0.04f, 0.06f)","tooltip":null,"header":null,"range":null,"order":19,"comment":null},{"name":"overrideReflection","type":"bool","default":null,"tooltip":null,"header":"Reflection - Realistic & Stylized only, needs a PlanarReflection component to show anything","range":null,"order":20,"comment":null},{"name":"reflectionStrength","type":"float","default":"0.5f","tooltip":null,"header":null,"range":"0f, 1f","order":21,"comment":null}],"src_members":[{"id":"Apply()","sig":"public void Apply()","kind":"method","name":"Apply","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":"Rendering/Water/Editor/WaterInstanceOverridesSelfTest.cs","src_demoScene":["Water_Demo"],"entryKind":"tool","status":"published","summary":"Per-instance water settings without a second material asset.","overview":["Override a water surface's visual settings on THIS INSTANCE only — two ponds sharing one material, where one has gentler waves and a murkier tint. It works through a MaterialPropertyBlock, so it costs no extra material and does not break batching."],"useCases":["Several ponds or pools with one material between them.","A calm inlet beside a choppy sea.","Tuning one water surface without touching the others."],"params":[{"field":"foamAmount","tuning":"Crest foam is Stylized only — it does nothing on Realistic or 2D."},{"field":"foamDistance","tuning":"Shoreline foam, and this one works on all three shaders."},{"field":"overrideWaves","tuning":"Each override group is gated by its own toggle, so you can override waves and leave colour to the material."}],"gotchas":[{"title":"Some settings apply to only one of the three shaders","body":"Crest foam is Stylized-only. Changing it on a Realistic surface does nothing, and the Inspector does not say so."}],"seeAlso":["RippleEmitter","PlanarReflection","WaterDepthTextureEnabler"],"src_uses":["PlanarReflection","RippleEmitter"],"src_usedBy":["RippleEmitter"],"src_extensionPoints":[]},{"id":"water-pour-visual","name":"WaterPourVisual","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Watering/WaterPourVisual.cs","src_lines":[11,160],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/Water Pour Visual"},"src_typeComment":"Two independent, combinable ways to SHOW a water pour — particles alone are cheap and read clearly as droplets; the shader stream alone is smoother and stays perfectly continuous even at very low pour rates where sparse particles would look broken up; both together give the densest look. This component only ever DRAWS whatever pour state it's handed via SetPour — it has no tilt/input logic of its own, so it stays reusable by anything that can compute a pour rate and an arc (typically WateringCanController).","src_serialized":[{"name":"waterColor","type":"Color","default":"new Color(0.55f, 0.75f, 0.95f, 0.85f)","tooltip":"Tint applied to both the particles and the stream.","header":"Common","range":null,"order":0,"comment":null},{"name":"enableParticles","type":"bool","default":"true","tooltip":null,"header":"Particles — droplet stream","range":null,"order":1,"comment":null},{"name":"maxEmissionRate","type":"float","default":"60f","tooltip":"Particles emitted per second at full pour rate (rate 1).","header":null,"range":null,"order":2,"comment":null},{"name":"particleSize","type":"float","default":"0.05f","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"particleSpeed","type":"float","default":"3f","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"enableStream","type":"bool","default":"true","tooltip":null,"header":"Stream — smooth curved shader stream","range":null,"order":5,"comment":null},{"name":"streamWidth","type":"float","default":"0.05f","tooltip":null,"header":null,"range":null,"order":6,"comment":null},{"name":"scrollSpeed","type":"float","default":"2f","tooltip":"How fast the flow texture scrolls along the stream — higher reads as faster-moving water.","header":null,"range":null,"order":7,"comment":null}],"src_members":[{"id":"SetPour(bool, float, Vector3[])","sig":"public void SetPour(bool isPouring, float rate01, Vector3[] arcPoints)","kind":"method","name":"SetPour","static":false,"comment":"Called every frame by whatever is driving the pour — typically WateringCanController — so this component never has to know about tilt or input itself."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["WateringCan_Demo"],"entryKind":"tool","status":"published","summary":"Two combinable ways to show a pour: particles, a shader stream, or both.","overview":["Particles alone are cheap and read clearly as droplets. The shader stream alone is smoother and stays continuous even at very low pour rates, where sparse particles would look broken. Both together give the densest look — they are independent toggles, not modes."],"useCases":["A watering can, jug or tap.","A low pour rate where particles would look like separate drops.","Matching a stylised art direction by choosing one or the other."],"params":[{"field":"maxEmissionRate","tuning":"At full pour rate. The actual rate scales with how far the can is tilted."},{"field":"scrollSpeed","tuning":"Higher reads as faster-moving water. Too high and the texture blurs into a flat band."}],"gotchas":[{"title":"It shows the pour, it does not decide it","body":"The controller computes the rate and hands it over. This component has no opinion about when water flows."}],"seeAlso":["WateringCanController","PlantWaterLevel"],"src_uses":["FakeLight","WateringCanController"],"src_usedBy":["EdgeGlowPattern","EdgeGlowShape","UIEdgeGlow","WateringCanController"],"src_extensionPoints":[]},{"id":"ui-edge-glow","name":"UIEdgeGlow","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/EdgeGlow/UIEdgeGlow.cs","src_lines":[21,358],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Graphic)"],"addComponentMenu":"Toolkit/Rendering/UI Edge Glow"},"src_typeComment":"Animated \"electric/flame\" edge glow for item frames, achievement icons, and rarity borders — a separate, more elaborate tool from UILightingEffect's Rim mode (which stays the simple, cheap, static edge-light it already is, for buttons/panels). Drop on any UI Graphic (Image, RawImage, ...) and pick a shape; the jagged/organic look comes from the scrolling, rotating noise mask, not the edge falloff itself, which is just a plain distance-to-edge band.","src_serialized":[{"name":"shape","type":"EdgeGlowShape","default":"EdgeGlowShape.Rectangle","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"edgeWidth","type":"float","default":"0.12f","tooltip":null,"header":null,"range":"0.01f, 0.5f","order":1,"comment":null},{"name":"edgeFalloff","type":"float","default":"1.5f","tooltip":null,"header":null,"range":"0.5f, 4f","order":2,"comment":null},{"name":"glowColor","type":"Color","default":"new Color(0.3f, 0.8f, 1f)","tooltip":null,"header":"Colour (Flame uses its own gradient below instead)","range":null,"order":3,"comment":null},{"name":"glowIntensity","type":"float","default":"2f","tooltip":null,"header":null,"range":"0f, 5f","order":4,"comment":null},{"name":"hueShiftSpeed","type":"float","default":"0f","tooltip":"Cycles per second the glow colour rotates through the hue wheel. 0 = a static colour.","header":null,"range":null,"order":5,"comment":null},{"name":"pattern","type":"EdgeGlowPattern","default":"EdgeGlowPattern.Noise","tooltip":"WHAT the mask looks like — each pattern computes the mask itself differently (not just a re-tint of the same noise). Fluid: a thin traced line wobbling via smooth domain-warped noise. Flow: the same domain-warp technique, but as a soft blobby alpha modulation instead of a thin line. Electric: a procedural angular zigzag (lightning), not static. Flame: dominant upward scroll with its own base→tip colour gradient below.","header":null,"range":null,"order":6,"comment":null},{"name":"chaseModeEnabled","type":"bool","default":null,"tooltip":null,"header":"Chase — an orthogonal TOGGLE, not a pattern: restricts whichever pattern above is active to a travelling comet + fading trail","range":null,"order":7,"comment":null},{"name":"chaseSpeed","type":"float","default":"0.4f","tooltip":null,"header":null,"range":"-3f, 3f","order":8,"comment":null},{"name":"chaseSpeedVariation","type":"float","default":"0.3f","tooltip":"0 = perfectly constant speed. Above 0 adds a surging/non-uniform feel to the travel instead of linear motion.","header":null,"range":"0f, 1f","order":9,"comment":null},{"name":"chaseTrailLength","type":"float","default":"0.18f","tooltip":"Fraction of the full perimeter the fading trail covers behind each travelling point.","header":null,"range":"0.02f, 0.6f","order":10,"comment":null},{"name":"chaseInstanceCount","type":"int","default":"1","tooltip":"How many comets travel the perimeter at once, evenly spaced. Overlapping trails take the brightest, never summed, so more instances can't blow out the exposure.","header":null,"range":"1, 8","order":11,"comment":null},{"name":"glowCoreWidth","type":"float","default":"0.3f","tooltip":"Fraction of Edge Width used for a tight bright inner core, on top of the normal mid band.","header":"Glow — shared 3-layer bloom (core + mid + soft outer bleed), applies to every pattern","range":"0.05f, 1f","order":12,"comment":null},{"name":"glowBloomWidth","type":"float","default":"2.5f","tooltip":"How many multiples of Edge Width the soft outer bloom reaches — this is what gives a genuine light-bleed feel instead of a hard-edged gradient.","header":null,"range":"1f, 4f","order":13,"comment":null},{"name":"glowBloomIntensity","type":"float","default":"0.5f","tooltip":null,"header":null,"range":"0f, 2f","order":14,"comment":null},{"name":"fluidWarpFrequency","type":"float","default":"2f","tooltip":null,"header":"Fluid — a THIN traced line (not a filled band) wobbling via smooth domain-warped noise","range":"0.5f, 8f","order":15,"comment":null},{"name":"fluidWarpStrength","type":"float","default":"0.5f","tooltip":null,"header":null,"range":"0f, 2f","order":16,"comment":null},{"name":"fluidDisplacementStrength","type":"float","default":"0.5f","tooltip":"How far the traced line wobbles in/out from the true edge. Kept modest relative to Edge Width so it reads as a flowing line hugging the boundary, not a solid shape reaching into the icon.","header":null,"range":"0f, 1.5f","order":17,"comment":null},{"name":"electricDisplacementStrength","type":"float","default":"0.35f","tooltip":"How far the traced line wobbles in/out from the true edge. Kept SMALL relative to Edge Width — a large value here is what used to make Electric read as spikes shooting inward instead of a thin line hugging the boundary.","header":"Electric — perimeter-jittered jagged path (chain lightning ALONG the edge) + stepped flicker","range":"0f, 1.5f","order":18,"comment":null},{"name":"electricEdgeFrequency","type":"float","default":"30f","tooltip":"Sampled along the PERIMETER (one texture row), not in 2D UV space — this is what gives a fine erratic zigzag travelling with the edge's own direction, instead of broad 2D waves. How many jitter cycles occur across one full trip around the border.","header":null,"range":"4f, 80f","order":19,"comment":null},{"name":"electricEdgeSpeed","type":"float","default":"0.15f","tooltip":null,"header":null,"range":null,"order":20,"comment":null},{"name":"electricFlickerSpeed","type":"float","default":"12f","tooltip":null,"header":null,"range":"1f, 30f","order":21,"comment":null},{"name":"electricFlickerIntensity","type":"float","default":"0.5f","tooltip":null,"header":null,"range":"0f, 1f","order":22,"comment":null},{"name":"electricInwardFadeAmount","type":"float","default":"0.4f","tooltip":"Keeps the jagged CORE line the dominant feature over the softer inward bleed (still present, just secondary) — 1 = equal weight, lower = edge pattern dominates.","header":null,"range":"0f, 1f","order":23,"comment":null},{"name":"electricUseRawTexture","type":"bool","default":null,"tooltip":"On: samples the Noise Mask directly (bright = displaced) so a hand-authored crackle texture drives the jitter as-is. Off (default): assumes raw unshaped noise and applies a ridge transform automatically.","header":null,"range":null,"order":24,"comment":null},{"name":"flameDisplacementStrength","type":"float","default":"1.5f","tooltip":null,"header":"Flame — its own colour gradient, base to tip (a solid filled push, not a thin line)","range":"0f, 3f","order":25,"comment":null},{"name":"flameBaseColor","type":"Color","default":"new Color(0.5f, 0.05f, 0f)","tooltip":null,"header":null,"range":null,"order":26,"comment":null},{"name":"flameMidColor","type":"Color","default":"new Color(1f, 0.45f, 0f)","tooltip":null,"header":null,"range":null,"order":27,"comment":null},{"name":"flameTipColor","type":"Color","default":"new Color(1f, 0.9f, 0.5f)","tooltip":null,"header":null,"range":null,"order":28,"comment":null},{"name":"noiseMask","type":"Texture2D","default":null,"tooltip":"Leave empty to auto-generate a turbulent noise mask.","header":"Edge Noise Mask — this is what gives the glow its jagged/organic look, not the edge falloff","range":null,"order":29,"comment":null},{"name":"maskTiling","type":"Vector2","default":"new Vector2(3f, 1f)","tooltip":null,"header":null,"range":null,"order":30,"comment":null},{"name":"maskScrollSpeed","type":"Vector2","default":"new Vector2(0f, 0.5f)","tooltip":null,"header":null,"range":null,"order":31,"comment":null},{"name":"maskPower","type":"float","default":"1f","tooltip":null,"header":null,"range":"0.1f, 4f","order":32,"comment":null},{"name":"initialRotation","type":"float","default":"0f","tooltip":null,"header":"Rotation & Radial Distortion","range":null,"order":33,"comment":null},{"name":"rotationSpeed","type":"float","default":"0f","tooltip":null,"header":null,"range":null,"order":34,"comment":null},{"name":"radialUVPower","type":"float","default":"0f","tooltip":"Pulls the mask sample toward/away from the centre based on distance, giving it a swirl instead of a flat scroll.","header":null,"range":"0f, 4f","order":35,"comment":null},{"name":"useChromaticAberration","type":"bool","default":null,"tooltip":null,"header":"Chromatic Aberration (optional)","range":null,"order":36,"comment":null},{"name":"chromaticAberrationOffset","type":"float","default":"0.01f","tooltip":null,"header":null,"range":"0f, 0.05f","order":37,"comment":null}],"src_members":[{"id":"MaterialInstance","sig":"public Material MaterialInstance => materialInstance","kind":"property","name":"MaterialInstance","static":false,"comment":null},{"id":"ApplySettings()","sig":"public void ApplySettings()","kind":"method","name":"ApplySettings","static":false,"comment":"Public so a self-test (or a runtime UI system) can push a settings change without waiting for OnValidate. The glow itself animates purely via the shader's own _Time.y — this does NOT need to be called every frame, only when a setting actually changes."}],"src_enumValues":[],"src_selfTest":"Rendering/UI/EdgeGlow/Editor/UIEdgeGlowSelfTest.cs","src_demoScene":["EdgeGlow_Demo"],"entryKind":"tool","status":"published","summary":"Animated electric, flame or fluid glow around a UI element's edge, with an optional chase.","overview":["An elaborate animated edge glow for item frames, achievement icons and rarity borders — deliberately a separate tool from the lighting effect's Rim mode, which stays the cheap static edge light for ordinary buttons and panels.","Pattern decides what the mask looks like; Chase is an orthogonal toggle that sends comets travelling the perimeter, and can be combined with any pattern."],"useCases":["Rarity borders on inventory items.","Drawing attention to an achievement or reward.","A charged or powered-up state on a UI element."],"params":[{"field":"pattern","tuning":"The big choice: what the mask actually looks like. Each pattern computes its mask differently rather than just tinting the same shape."},{"field":"chaseModeEnabled","tuning":"Orthogonal to pattern — you can chase any of them. It is not a pattern of its own."},{"field":"chaseInstanceCount","tuning":"Comets travelling at once, evenly spaced. More than three or four reads as a solid moving band rather than distinct comets."},{"field":"electricUseRawTexture","tuning":"A debugging aid as much as a look: it shows the noise mask directly, which is how the Electric pattern's real bug was originally found."},{"field":"glowBloomWidth","tuning":"Multiples of Edge Width. Large values soften the effect into a haze and stop reading as an edge."},{"field":"noiseMask","tuning":"Leave empty to auto-generate a turbulent mask, which is tuned for these patterns."}],"gotchas":[{"title":"It has a lot of settings, most pattern-specific","body":"The Electric, Flame and Fluid groups only affect their own pattern. Changing a flame setting while on Electric does nothing."},{"title":"It instances the material","body":"Each component gets its own material instance so settings do not bleed between elements. That is correct and means more draw calls with many of them on screen."}],"seeAlso":["UILightingEffect","UIRippleEffect"],"src_uses":["EdgeGlowPattern","EdgeGlowShape","FakeLight","UILightingEffect","WaterPourVisual"],"src_usedBy":["EdgeGlowPattern","EdgeGlowShape"],"src_extensionPoints":[],"parts":[{"id":"edge-glow-pattern","name":"EdgeGlowPattern","cat":"Rendering","src_typeKind":"enum","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/EdgeGlow/UIEdgeGlow.cs","src_lines":[12,12],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"WHAT the mask/displacement looks like, not just how it's tinted — each pattern computes it itself differently (see UIEdgeGlow.shader), not a re-tint of the same turbulence. Chase is NOT here — it is a separate, orthogonal toggle (see chaseModeEnabled below) that restricts WHATEVER pattern is picked here to a travelling comet+trail, so any pattern's own look can become a travelling comet.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"WHAT the mask/displacement looks like, not just how it's tinted — each pattern computes it itself differently (see...","src_uses":["EdgeGlowShape","FakeLight","UIEdgeGlow","UILightingEffect","WaterPourVisual"],"src_usedBy":["EdgeGlowShape","UIEdgeGlow"],"src_extensionPoints":[],"foldedInto":"ui-edge-glow"},{"id":"edge-glow-shape","name":"EdgeGlowShape","cat":"Rendering","src_typeKind":"enum","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/EdgeGlow/UIEdgeGlow.cs","src_lines":[6,6],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["EdgeGlowPattern","FakeLight","UIEdgeGlow","UILightingEffect","WaterPourVisual"],"src_usedBy":["EdgeGlowPattern","UIEdgeGlow"],"src_extensionPoints":[],"foldedInto":"ui-edge-glow"}]},{"id":"ui-blur-source","name":"UIBlurSource","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/GlassBlur/UIBlurSource.cs","src_lines":[19,152],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Camera)"],"addComponentMenu":"Toolkit/Rendering/UI Blur Source"},"src_typeComment":"Drop on the MAIN CAMERA (whatever camera renders the 3D/2D scene the UI sits over) to capture and blur its view into ONE shared, deliberately LOW-RESOLUTION RenderTexture, published via Shader.SetGlobalTexture — every Toolkit/UI/Glass Blur material samples the exact same texture automatically, no per-element wiring needed. This is the whole point versus GrabPass: one controlled, low-res copy shared by every glass element per frame, not a fresh full-resolution screen copy per object (see the GrabPass explanation this tool was built after).  Captured via a SEPARATE camera on OnPostRender, not the actual player camera's own output — this keeps the capture from ever including the UI Canvas itself (Screen Space Overlay UI renders after and outside normal camera rendering entirely, so it's naturally excluded; a Screen Space Camera canvas assigned to THIS SAME camera would need its own render layer excluded from `reflectionMask`-style filtering, which isn't set up here since the toolkit's own demo — and the common case — uses Overlay).","src_serialized":[{"name":"resolutionScale","type":"float","default":"0.25f","tooltip":"Capture resolution as a fraction of the screen. Quarter (0.25) is the deliberate default — blur wants low resolution anyway, and this is the actual cost lever.","header":null,"range":"0.05f, 1f","order":0,"comment":null},{"name":"blurPasses","type":"int","default":"3","tooltip":"Box-blur passes to apply. Repeated box blur cheaply approximates a Gaussian blur — more passes = smoother/blurrier, more cost.","header":null,"range":"1, 8","order":1,"comment":null},{"name":"blurSpread","type":"float","default":"1.5f","tooltip":"Blur sample spread, in texels of the LOW-RES capture. Larger spreads the blur wider per pass.","header":null,"range":"0.5f, 4f","order":2,"comment":null},{"name":"captureEveryNFrames","type":"int","default":"1","tooltip":"Re-captures every N frames instead of every frame — the background behind glass rarely needs to be perfectly current.","header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"ForceCapture()","sig":"public void ForceCapture()","kind":"method","name":"ForceCapture","static":false,"comment":"Public so it can be triggered outside the normal per-frame OnPostRender schedule — a self-test driving it directly (OnPostRender never fires outside an actual camera render pass, which batch mode doesn't perform), or a game explicitly wanting one fresh capture right before opening a menu."}],"src_enumValues":[],"src_selfTest":"Rendering/UI/GlassBlur/Editor/UIBlurSourceSelfTest.cs","src_demoScene":["GlassBlur_Demo"],"entryKind":"tool","status":"published","summary":"Captures and blurs the camera's view once into a shared low-res texture every glass material samples.","overview":["Drop it on the camera that renders the scene behind the UI. It captures and blurs that view into ONE shared, deliberately low-resolution RenderTexture published globally, so every glass-blur material samples the same texture with no per-element setup and no per-element cost."],"useCases":["Frosted-glass panels over gameplay.","A blurred pause-menu backdrop.","Any glass effect where a per-element blur would be too expensive."],"params":[{"field":"resolutionScale","tuning":"Low is the point — a quarter is usually indistinguishable once blurred, and costs a sixteenth of the pixels."},{"field":"blurPasses","tuning":"Repeated box blur cheaply approximates a Gaussian. Two or three passes is usually enough; more costs more for little visible gain."},{"field":"captureEveryNFrames","tuning":"The main cost control. A static pause menu can capture once and never again."}],"gotchas":[{"title":"One source for the whole scene","body":"It is a global texture, so every glass material shares it. Two cameras needing different blurred backdrops is not something this supports."},{"title":"It captures the camera's view, so UI drawn over it is not included","body":"Which is correct — otherwise the blur would feed back on itself."}],"seeAlso":["UILightingEffect"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"ui-ripple-effect","name":"UIRippleEffect","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/UI/RippleDistortion/UIRippleEffect.cs","src_lines":[15,108],"src_base":"MonoBehaviour","src_implements":["IPointerClickHandler"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Graphic)","typeof(RectTransform)"],"addComponentMenu":"Toolkit/Rendering/UI Ripple Effect"},"src_typeComment":"Drop on any UI Graphic (Image, RawImage, ...) — clicking it fires an expanding \"shockwave\" ripple from the click point (Toolkit/UI/Ripple Distortion shader), both warping the sampled UV and pulsing a highlight along the ring. One ripple at a time: clicking again mid-ripple just restarts it at the new point, matching how most \"material ripple\" button effects behave (this is a UI polish effect, not a multi-ripple simulation).","src_serialized":[{"name":"rippleSpeed","type":"float","default":"1.4f","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"rippleWidth","type":"float","default":"0.08f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"rippleDuration","type":"float","default":"0.6f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"distortStrength","type":"float","default":"0.08f","tooltip":null,"header":null,"range":"0f, 0.3f","order":3,"comment":null},{"name":"highlightColor","type":"Color","default":"Color.white","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"highlightStrength","type":"float","default":"1f","tooltip":null,"header":null,"range":"0f, 3f","order":5,"comment":null}],"src_members":[{"id":"MaterialInstance","sig":"public Material MaterialInstance => materialInstance","kind":"property","name":"MaterialInstance","static":false,"comment":null},{"id":"ApplySettings()","sig":"public void ApplySettings()","kind":"method","name":"ApplySettings","static":false,"comment":"Public so a self-test (or OnValidate) can push a settings change without waiting for a real click."},{"id":"OnPointerClick(PointerEventData)","sig":"public void OnPointerClick(PointerEventData eventData)","kind":"method","name":"OnPointerClick","static":false,"comment":null},{"id":"TriggerRippleAtLocalPoint(Vector2)","sig":"public void TriggerRippleAtLocalPoint(Vector2 localPoint)","kind":"method","name":"TriggerRippleAtLocalPoint","static":false,"comment":"Public and separated from OnPointerClick so a self-test — or any non-pointer trigger, like a gamepad \"confirm\" action — can start a ripple at a known point without simulating a real click."},{"id":"TriggerRipple()","sig":"public void TriggerRipple() => TriggerRippleAtLocalPoint(rectTransform.rect.center)","kind":"method","name":"TriggerRipple","static":false,"comment":"Convenience for a programmatic \"pulse\" (e.g. a purchase confirmation, a notification badge) rather than a real pointer click — ripples from the element's own centre."}],"src_enumValues":[],"src_selfTest":"Rendering/UI/RippleDistortion/Editor/UIRippleEffectSelfTest.cs","src_demoScene":["UIRipple_Demo"],"entryKind":"tool","status":"published","summary":"Click a UI element and a shockwave ripple expands from the click point.","overview":["Drop it on any UI Graphic. Clicking fires an expanding ripple from the click point, warping the sampled UVs and pulsing a highlight along the ring. One ripple at a time — clicking again mid-ripple restarts it at the new point rather than layering."],"useCases":["Material-style touch feedback on buttons and cards.","Making a large flat panel feel responsive to touch.","A hit or impact pulse on a UI element."],"params":[{"field":"distortStrength","tuning":"Subtle is the point. High values visibly tear the image rather than reading as a ripple."},{"field":"rippleDuration","tuning":"Long durations mean a second click cancels the first mid-flight, which can read as unresponsive."}],"gotchas":[{"title":"One ripple at a time, by design","body":"Rapid clicking restarts rather than accumulating. That keeps the shader cheap and is a visual limitation to know about."}],"seeAlso":["UIEdgeGlow","RippleEmitter"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"dissolve-effect","name":"DissolveEffect","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Dissolve/DissolveEffect.cs","src_lines":[12,46],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Rendering/Dissolve Effect"},"src_typeComment":"Drop alongside a Renderer using the Toolkit/Dissolve/Dissolve shader — call PlayDissolveOut() (e.g. on death) or PlayDissolveIn() (e.g. on spawn) to animate the shader's _DissolveAmount over time. Uses .material (not sharedMaterial) so each instance animates independently without affecting others sharing the same source material asset.","src_serialized":[{"name":"duration","type":"float","default":"1.5f","tooltip":"Seconds the dissolve animation takes.","header":null,"range":null,"order":0,"comment":null},{"name":"destroyOnDissolveOut","type":"bool","default":"true","tooltip":"Destroys this GameObject when a dissolve-out finishes.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"PlayDissolveOut()","sig":"public void PlayDissolveOut() => Play(0f, 1f, destroyOnDissolveOut)","kind":"method","name":"PlayDissolveOut","static":false,"comment":null},{"id":"PlayDissolveIn()","sig":"public void PlayDissolveIn() => Play(1f, 0f, false)","kind":"method","name":"PlayDissolveIn","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["VFXShaders_Demo"],"entryKind":"tool","status":"published","summary":"Animates a dissolve shader's amount for a spawn or death transition.","overview":["Drop it alongside a Renderer using the dissolve shader and call the play methods to animate the effect over time. It uses .material rather than .sharedMaterial so each instance animates independently without affecting everything sharing that material."],"useCases":["Enemies dissolving on death instead of vanishing.","Spawning something in rather than popping it in.","A teleport or phase transition."],"params":[{"field":"destroyOnDissolveOut","tuning":"Convenient for a death effect, and wrong for a pooled object — it destroys rather than releasing."}],"gotchas":[{"title":".material instances the material","body":"That is what makes instances independent, and it means a new material per object and an extra draw call. Unavoidable for per-instance animation."},{"title":"It needs the dissolve shader","body":"On any other material the property does not exist and nothing happens."}],"seeAlso":["ShaderTransitionManager","HologramEffect"],"src_uses":[],"src_usedBy":["ShaderTransitionManager"],"src_extensionPoints":[]},{"id":"force-field-effect","name":"ForceFieldEffect","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/ForceField/ForceFieldEffect.cs","src_lines":[10,39],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Rendering/Force Field Effect"},"src_typeComment":"Drop alongside a Renderer using the Toolkit/ForceField/ForceField shader — call TriggerHitFlash() (e.g. from a Health.OnDamaged listener) for a brief bright flash on impact.","src_serialized":[{"name":"flashDecayTime","type":"float","default":"0.3f","tooltip":"Seconds the hit flash takes to fade back to 0.","header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"TriggerHitFlash()","sig":"public void TriggerHitFlash()","kind":"method","name":"TriggerHitFlash","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["VFXShaders_Demo"],"entryKind":"tool","status":"published","summary":"Flashes a force-field shader brightly on impact.","overview":["Drop it alongside a Renderer using the force-field shader and call TriggerHitFlash on impact — typically from a Health damage event — for a brief bright pulse."],"useCases":["A shield bubble reacting to being shot.","A barrier the player can see is being hit.","Any surface that should flash where it is struck."],"gotchas":[{"title":"The flash is global to the material, not at the hit point","body":"The whole field brightens rather than rippling from where it was hit. The ripple emitter is the tool for a positioned reaction."}],"seeAlso":["Health","RippleEmitter"],"src_uses":["Health"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"glitch-effect","name":"GlitchEffect","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Glitch/GlitchEffect.cs","src_lines":[11,35],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Rendering/Glitch Effect"},"src_typeComment":"Drop alongside a Renderer using the Toolkit/Glitch/Glitch shader — TriggerGlitch() punches _GlitchAmount up then eases it back to 0, e.g. on taking damage or a \"corrupted\" story beat.","src_serialized":[{"name":"decayDuration","type":"float","default":"0.5f","tooltip":"Seconds for the glitch burst to ease back down to 0.","header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"TriggerGlitch(float)","sig":"public void TriggerGlitch(float intensity = 1f)","kind":"method","name":"TriggerGlitch","static":false,"comment":null},{"id":"SetGlitchAmount(float)","sig":"public void SetGlitchAmount(float amount)","kind":"method","name":"SetGlitchAmount","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["VFXShaders_Demo"],"entryKind":"tool","status":"published","summary":"Punches a glitch shader's amount up and eases it back down.","overview":["Drop it alongside a Renderer using the glitch shader. TriggerGlitch punches the amount up then eases it back to zero — for taking damage, or a corrupted story beat."],"useCases":["A damage or interference reaction.","A corrupted or malfunctioning object.","Punctuating a narrative moment."],"gotchas":[{"title":"Retriggering restarts rather than stacking","body":"Rapid triggers hold it near full rather than compounding. For escalating intensity, drive the amount directly."}],"seeAlso":["DissolveEffect","CameraShake"],"src_uses":["EaseType","Tween","TweenHandle"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"hologram-effect","name":"HologramEffect","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Hologram/HologramEffect.cs","src_lines":[11,39],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Rendering/Hologram Effect"},"src_typeComment":"Drop alongside a Renderer using the Toolkit/Hologram/Hologram shader — SetVisible() tweens _Alpha via the Tween engine for a materialize/dematerialize transition instead of an instant on/off.","src_serialized":[{"name":"fadeDuration","type":"float","default":"0.4f","tooltip":"Seconds the materialize/dematerialize fade takes.","header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"SetVisible(bool, bool)","sig":"public void SetVisible(bool visible, bool animated = true)","kind":"method","name":"SetVisible","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["VFXShaders_Demo"],"entryKind":"tool","status":"published","summary":"Tweens a hologram shader's alpha for a materialise or dematerialise transition.","overview":["Drop it alongside a Renderer using the hologram shader. SetVisible tweens the alpha through the tween engine so the object fades in or out rather than snapping."],"useCases":["A projected hologram appearing and disappearing.","A sci-fi UI element materialising in world space.","A ghostly or phased-out enemy state."],"gotchas":[{"title":"It fades the shader, not the object","body":"The renderer stays enabled at zero alpha. Disable it yourself if invisible should also mean free."}],"seeAlso":["DissolveEffect","Tween"],"src_uses":["EaseType","Tween","TweenHandle"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"highlight-toggle","name":"HighlightToggle","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Highlight/HighlightToggle.cs","src_lines":[10,64],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/Highlight Toggle"},"src_typeComment":"Toggleable highlight outline for EITHER a 3D mesh (assign a material using Toolkit/Highlight/Outline3D) or a 2D sprite (assign one using Toolkit/Highlight/OutlineSprite) — works with whichever Renderer type is on this GameObject (MeshRenderer or SpriteRenderer). The outline material is appended as an EXTRA material slot rather than replacing the object's own material, so its normal appearance is untouched.","src_serialized":[{"name":"outlineMaterial","type":"Material","default":null,"tooltip":"Material using Toolkit/Highlight/Outline3D (mesh) or Toolkit/Highlight/OutlineSprite (sprite). Safe to share the same material across every highlighted object — it has no per-instance animated state.","header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"IsHighlighted","sig":"public bool IsHighlighted { get; private set; }","kind":"property","name":"IsHighlighted","static":false,"comment":null},{"id":"EnableHighlight()","sig":"public void EnableHighlight()","kind":"method","name":"EnableHighlight","static":false,"comment":null},{"id":"DisableHighlight()","sig":"public void DisableHighlight()","kind":"method","name":"DisableHighlight","static":false,"comment":null},{"id":"ToggleHighlight()","sig":"public void ToggleHighlight()","kind":"method","name":"ToggleHighlight","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["VFXShaders_Demo"],"entryKind":"tool","status":"published","summary":"Toggleable outline for either a mesh or a sprite, using whichever renderer is present.","overview":["An outline you can switch on and off, working with a MeshRenderer or a SpriteRenderer depending on what is on the object — assign the matching outline material. The outline material is appended to the renderer rather than replacing the existing one."],"useCases":["Highlighting a selected unit or interactable.","Showing what is under the cursor.","Marking a quest target."],"params":[{"field":"outlineMaterial","tuning":"There are two shaders — one for 3D meshes, one for sprites. The wrong one produces no visible outline rather than an error."}],"gotchas":[{"title":"Appending a material adds a draw call","body":"Which is how it outlines without replacing the object's look. Highlighting hundreds of objects at once is not free."}],"seeAlso":["ClickToSelect","MaterialPropertyBlockHelper"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"weapon-trail","name":"WeaponTrail","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/VFX/WeaponTrail/WeaponTrail.cs","src_lines":[16,84],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(TrailRenderer)"],"addComponentMenu":"Toolkit/Rendering/Weapon Trail"},"src_typeComment":"Drop on a weapon's tip/edge (a thin child transform near the blade, since a TrailRenderer draws from wherever ITS OWN transform has physically moved — this component just centralizes TrailRenderer's many scattered settings into a few clean Inspector fields with sensible defaults, and adds SetTrailActive() for the actual gameplay use case: turn the trail on for the duration of a swing, off otherwise, rather than leaving it emitting constantly.  Pair with Toolkit/VFX/Weapon Trail (an additive glow shader) on the TrailRenderer's material for the stylized energy-trail look — TrailRenderer works with any material, this component doesn't require that specific shader.","src_serialized":[{"name":"trailTime","type":"float","default":"0.25f","tooltip":"How long a point stays part of the trail before fading out of the tail end.","header":null,"range":null,"order":0,"comment":null},{"name":"startWidth","type":"float","default":"0.3f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"endWidth","type":"float","default":"0f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"colorGradient","type":"Gradient","default":"CreateDefaultGradient()","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"activeOnStart","type":"bool","default":"true","tooltip":"Whether the trail starts emitting immediately on Awake — turn off if a combat system will call SetTrailActive(true) itself when a swing begins.","header":null,"range":null,"order":4,"comment":null}],"src_members":[{"id":"SetTrailActive(bool)","sig":"public void SetTrailActive(bool active)","kind":"method","name":"SetTrailActive","static":false,"comment":"Turns new-point emission on/off — call true at the start of a swing, false at the end. Already- emitted points still fade out naturally over `trailTime` rather than the trail vanishing instantly, which is what TrailRenderer.emitting (not Clear() or enabled) is specifically for."},{"id":"ClearTrail()","sig":"public void ClearTrail()","kind":"method","name":"ClearTrail","static":false,"comment":"Immediately removes every existing point — use when a weapon teleports/is re-equipped and the OLD trail position would otherwise draw a visible streak across the jump."}],"src_enumValues":[],"src_selfTest":"Rendering/VFX/WeaponTrail/Editor/WeaponTrailSelfTest.cs","src_demoScene":["WeaponTrail_Demo"],"entryKind":"tool","status":"published","summary":"Centralises TrailRenderer's scattered settings into a few fields, plus on/off control.","overview":["Drop it on a thin child transform near the blade's edge, since a TrailRenderer draws from wherever ITS OWN transform has physically moved. The component gathers TrailRenderer's many scattered settings into a few clean fields with sensible defaults and adds explicit activation."],"useCases":["A sword or claw trail during a swing.","A projectile or dash trail.","Turning a trail on only during active frames."],"params":[{"field":"trailTime","tuning":"How long the trail persists. Long values on a fast swing leave a ribbon hanging in the air after the attack ends."},{"field":"activeOnStart","tuning":"Usually off — a weapon trail that is always on removes the emphasis of the swing."}],"gotchas":[{"title":"It trails the transform it is ON","body":"Put it on a child at the blade's edge, not on the weapon root, or the trail comes from the hilt."},{"title":"Toggling off leaves the existing trail fading","body":"Clear it explicitly if a teleport should not drag a trail across the screen."}],"seeAlso":["MeleeAttack","Hitbox"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"decals","name":"Decals","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Decals/DecalProjector.cs","src_lines":[16,110],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/Decal Projector"},"src_typeComment":"Drop on an empty GameObject positioned/rotated/scaled to define the decal's PROJECTION BOX — the object's local -Y axis is the projection direction (\"down onto the surface\"), local X/Z are the decal's footprint, and localScale sets the box size on all 3 axes (a Cube-primitive-style gizmo, drawn below, shows exactly where it will project) — then call Generate() (or use the \"Generate Decal\" context-menu entry) to spawn a real mesh clipped to whatever geometry sits inside the box.  Requires the receiving surface to carry BOTH a Collider (found via Physics.OverlapBox) AND a MeshFilter on the SAME GameObject (its triangles are what actually get clipped) — the normal \"mesh + matching MeshCollider\" setup most scene geometry already has.","src_serialized":[{"name":"surfaceMask","type":"LayerMask","default":"~0","tooltip":"Which colliders count as receiving surfaces for this decal.","header":null,"range":null,"order":0,"comment":null},{"name":"decalMaterial","type":"Material","default":null,"tooltip":"Material applied to the generated decal mesh — needs a decal texture with alpha (a tire-mark or footprint shape, transparent elsewhere).","header":null,"range":null,"order":1,"comment":null},{"name":"maxSurfaceAngle","type":"float","default":"60f","tooltip":"A source triangle whose normal points more than this many degrees away from the projection direction is skipped, so a floor decal doesn't wrap up onto a nearby wall.","header":null,"range":"1f, 89f","order":2,"comment":null},{"name":"surfaceOffset","type":"float","default":"0.01f","tooltip":"Small push outward along each vertex's own normal, avoiding z-fighting with the receiving geometry.","header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"GeneratedVertexCount","sig":"public int GeneratedVertexCount => generatedInstance != null ? generatedInstance.GetComponent<MeshFilter>().sharedMesh.vertexCount : 0","kind":"property","name":"GeneratedVertexCount","static":false,"comment":null},{"id":"Generate()","sig":"public GameObject Generate()","kind":"method","name":"Generate","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":"Rendering/Decals/Editor/DecalProjectorSelfTest.cs","src_demoScene":["Decals_Demo"],"entryKind":"tool","status":"published","summary":"Defines a projection box; the decal mesh is built from the geometry inside it.","overview":["Position, rotate and scale an empty object to define the box. Local -Y is the projection direction — down onto the surface — local X and Z are the footprint, and the scale sets the box size. The decal is then generated from the receiving geometry inside that box."],"useCases":["Bullet holes, scorch marks and blood splatter.","Painted markings on curved or uneven ground.","Signage that follows the surface it lands on."],"params":[{"field":"maxSurfaceAngle","tuning":"Rejects triangles facing too far from the projection direction, which is what stops a decal smearing down a wall it only grazes."},{"field":"surfaceOffset","tuning":"A small push along each vertex normal to avoid z-fighting. Too much and the decal visibly floats."},{"field":"surfaceMask","tuning":"Which colliders can receive it. Include the ground and walls; exclude characters unless you want decals on them."}],"gotchas":[{"title":"It generates geometry, it does not render a quad","body":"The decal is built from the receiving surface's own triangles, which is why it follows curves correctly and why a complex surface produces more vertices."},{"title":"It is generated, not live","body":"Moving the receiving geometry afterwards leaves the decal where it was. Regenerate if the surface moves."}],"seeAlso":["DecalMeshBuilder"],"src_uses":["DecalMeshBuilder"],"src_usedBy":[],"src_extensionPoints":[],"isSystem":true,"systemOf":"DecalProjector","systemPrimaryId":"decal-projector","systemSections":[{"title":"Supporting scripts","entries":[{"id":"decal-mesh-builder","name":"DecalMeshBuilder","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Decals/DecalMeshBuilder.cs","src_lines":[22,128],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"The actual \"mesh-projected decal\" technique: clips each candidate source triangle against a unit projection BOX (Sutherland-Hodgman, one pass per box face) rather than rendering a flat quad on top of the surface or splatting into a render texture — the decal is built FROM the receiving geometry's own triangles, so it follows curved/uneven surfaces exactly rather than floating or clipping through them. Pure and stateless (candidate triangles passed in, a Mesh handed back) so the clipping math is testable with synthetic triangles, no scene/GameObjects required.","src_serialized":[],"src_members":[{"id":"Build()","sig":"public static Mesh Build(","kind":"method","name":"Build","static":true,"comment":"candidateTriangles: each entry is one source triangle as (a, b, c, normal), all in WORLD space. worldToDecal / decalToWorld: the projection box's own transform, sized so decal-local space IS the [-0.5, 0.5] unit cube (i.e. built from Matrix4x4.TRS(position, rotation, boxSize)). maxSurfaceAngleDegrees: a triangle whose normal points more than this many degrees away from straight down the box's local -Y axis (the projection direction) is skipped entirely — keeps a floor decal from wrapping onto a nearby wall. surfaceOffset: world-space push along each vertex's own normal, away from the surface, to avoid z-fighting with the geometry the decal sits on."}],"src_enumValues":[],"src_selfTest":"Rendering/Decals/Editor/DecalMeshBuilderSelfTest.cs","src_demoScene":[],"entryKind":"tool","status":"published","summary":"The clipping technique itself: source triangles clipped against the projection box.","overview":["Clips each candidate source triangle against a unit projection box, one pass per box face, rather than rendering a flat quad on top or splatting into a render texture. Building the decal FROM the receiving geometry is what makes it follow curves and corners exactly."],"useCases":["Generating decal meshes from your own tooling.","Understanding or adapting the clipping approach.","Building decals at import time rather than at runtime."],"gotchas":[{"title":"Cost scales with the receiving geometry's density","body":"A decal on a high-poly surface clips many more triangles than one on a flat plane. Keep projection boxes tight."}],"seeAlso":["DecalProjector"],"src_uses":["DecalVertex"],"src_usedBy":["DecalProjector","DecalVertex","LtgSnapToMouseTab"],"src_extensionPoints":[],"parts":[{"id":"decal-vertex","name":"DecalVertex","cat":"Rendering","src_typeKind":"struct","src_ns":"Toolkit.Rendering","src_file":"Rendering/Decals/DecalMeshBuilder.cs","src_lines":[10,14],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"One clipped-polygon vertex, carried through Sutherland-Hodgman clipping. `position` is in DECAL-LOCAL space (the projection box normalized to the [-0.5, 0.5] unit cube); `normal` is WORLD space, kept for per-vertex lighting/orientation on the final mesh — interpolated at clip points the same way position is, so a decal wrapping a curved surface shades smoothly instead of faceted per source triangle.","src_serialized":[],"src_members":[{"id":"position","sig":"public Vector3 position","kind":"field","name":"position","static":false,"comment":null},{"id":"normal","sig":"public Vector3 normal","kind":"field","name":"normal","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"data","status":"skeleton","summary":"One clipped-polygon vertex, carried through Sutherland-Hodgman clipping.","src_uses":["DecalMeshBuilder"],"src_usedBy":["DecalMeshBuilder"],"src_extensionPoints":[],"foldedInto":"decal-mesh-builder"}]}]}]},{"id":"grass-bend-emitter","name":"GrassBendEmitter","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/Grass/GrassBendEmitter.cs","src_lines":[13,83],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Rendering/Grass Bend Emitter"},"src_typeComment":"Drop this on a character/object walking through grass — it publishes its own position into a GLOBAL array every GrassWind-shaded renderer in the scene reads (see GrassInclude.cginc), so any number of grass patches react with zero per-patch wiring. This is a deliberate divergence from RippleEmitter's per-renderer MaterialPropertyBlock approach: a ripple emitter lives ON the one surface it affects, but a grass field is typically many separate renderers and the walker is a DIFFERENT object from all of them — a global array is what lets one emitter affect every patch in the level at once.","src_serialized":[{"name":"bendRadius","type":"float","default":"1.2f","tooltip":"How far from this object grass starts bending away.","header":null,"range":null,"order":0,"comment":null},{"name":"bendStrength","type":"float","default":"0.4f","tooltip":"Peak horizontal push a blade standing right at this object gets. Combined across every active emitter by taking the LARGEST value among them — see the class comment on Publish().","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"MaxInfluencers","sig":"public const int MaxInfluencers = 8","kind":"const","name":"MaxInfluencers","static":false,"comment":"Must match TOOLKIT_MAX_GRASS_INFLUENCERS in GrassInclude.cginc."},{"id":"Publish()","sig":"public static void Publish()","kind":"method","name":"Publish","static":true,"comment":"Public — not gated behind Update() — so a self-test can drive this deterministically without waiting on a real frame, same reasoning as every other \"public Tick-equivalent\" in this toolkit."},{"id":"ActiveEmitterCountForTest","sig":"public static int ActiveEmitterCountForTest => ActiveEmitters.Count","kind":"property","name":"ActiveEmitterCountForTest","static":true,"comment":"Test-only accessors — reading GLOBAL shader state back isn't otherwise observable from a script in a way a self-test can assert against."},{"id":"PublishedSlotForTest(int)","sig":"public static Vector4 PublishedSlotForTest(int index) => PositionsBuffer[index]","kind":"method","name":"PublishedSlotForTest","static":true,"comment":null},{"id":"ResetPublishGuardForTest()","sig":"public static void ResetPublishGuardForTest() => lastPublishedFrame = -1","kind":"method","name":"ResetPublishGuardForTest","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":"Rendering/Grass/Editor/GrassBendEmitterSelfTest.cs","src_demoScene":["Grass_Demo"],"entryKind":"tool","status":"published","summary":"Publishes its position globally so every grass-shaded renderer bends away, with no per-patch wiring.","overview":["Drop it on a character walking through grass. It publishes its position into a GLOBAL array that every grass-shaded renderer reads, so any number of grass patches react with zero wiring per patch — a deliberate divergence from the ripple emitter, which drives its own material's block instead."],"useCases":["A character parting grass as they walk.","Vehicles or creatures flattening vegetation.","Many grass patches reacting without connecting each one."],"params":[{"field":"bendRadius","tuning":"How far the influence reaches. Too large and a whole field leans at once, which reads as wind rather than footsteps."},{"field":"bendStrength","tuning":"The push on a blade standing right at the object. Extreme values lay grass flat and look broken."}],"gotchas":[{"title":"A fixed-size global array caps the emitters","body":"Beyond the limit, extra emitters are dropped. Put it on the player and a few key creatures, not on everything."}],"seeAlso":["RippleEmitter","FakeLight"],"src_uses":["RippleEmitter"],"src_usedBy":["FakeLight","FakeLightInfluenceMode","FakeLightType","UIFakeLight","UIFakeLightType"],"src_extensionPoints":[]},{"id":"speed-radial-blur","name":"SpeedRadialBlur","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/PostProcessing/RadialBlur/SpeedRadialBlur.cs","src_lines":[13,74],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Camera)"],"addComponentMenu":"Toolkit/Rendering/Speed Radial Blur"},"src_typeComment":"Drop on the MAIN CAMERA for a full-screen \"going fast\" radial blur that eases in/out with speed — call SetSpeed01(0..1) every frame from whatever drives the vehicle/character's actual speed (e.g. rigidbody.velocity.magnitude / topSpeed). A camera image-effect (OnRenderImage), the classic Built-in RP way to do a full-screen post-process — genuinely costs a full extra Blit pass across the whole screen, which is the deliberate trade for the most immersive version of this effect (a cheaper stylized speed-line overlay is a different tool for when that cost isn't worth it).","src_serialized":[{"name":"maxBlurAmount","type":"float","default":"0.1f","tooltip":"Blur strength at full speed (speed01 = 1), as a fraction of the screen. 0.08-0.15 is a reasonable range before it gets disorienting.","header":null,"range":"0f, 0.3f","order":0,"comment":null},{"name":"smoothing","type":"float","default":"8f","tooltip":"Higher = the blur reacts to a speed change more quickly; lower = more lag easing in/out.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"CurrentBlurAmount","sig":"public float CurrentBlurAmount => currentBlurAmount","kind":"property","name":"CurrentBlurAmount","static":false,"comment":null},{"id":"SetSpeed01(float)","sig":"public void SetSpeed01(float speed01) => targetSpeed01 = Mathf.Clamp01(speed01)","kind":"method","name":"SetSpeed01","static":false,"comment":"0 = stationary (no blur), 1 = full speed (maxBlurAmount). Values outside [0,1] are clamped, so feeding a raw speed/topSpeed ratio that can briefly exceed 1 (e.g. a boost) is safe as-is."},{"id":"Tick(float)","sig":"public void Tick(float deltaTime)","kind":"method","name":"Tick","static":false,"comment":"The actual smoothing logic, pulled out of Update() so it can be driven deterministically by a self- test — Time.deltaTime is meaningless outside Play mode, and OnRenderImage never fires outside an actual camera render pass either, so this is the one piece of the effect a headless test CAN drive."}],"src_enumValues":[],"src_selfTest":"Rendering/PostProcessing/RadialBlur/Editor/SpeedRadialBlurSelfTest.cs","src_demoScene":["RadialBlur_Demo"],"entryKind":"tool","status":"published","summary":"Full-screen radial blur that eases in with speed. Drop it on the main camera.","overview":["A \"going fast\" radial blur driven by a normalised speed you feed it each frame — typically velocity magnitude over top speed. A camera image effect using OnRenderImage, which is the classic Built-in RP approach."],"useCases":["Racing games where speed should be felt.","A sprint or dash effect.","A boost or overdrive state."],"params":[{"field":"maxBlurAmount","tuning":"Subtle works. Enough blur to notice consciously is usually enough to induce motion sickness."},{"field":"smoothing","tuning":"Stops the blur snapping on and off with speed changes. Higher reacts faster."}],"gotchas":[{"title":"You must feed it the speed","body":"It has no idea how fast anything is going. Without a per-frame SetSpeed01 it does nothing."},{"title":"Built-in RP only","body":"OnRenderImage is not how URP or HDRP do post-processing. This project is Built-in RP throughout."}],"seeAlso":["CameraShake","PlayerCameraRig"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"material-property-block-helper","name":"MaterialPropertyBlockHelper","cat":"Rendering","src_typeKind":"class","src_ns":"Toolkit.Rendering","src_file":"Rendering/MaterialPropertyBlockHelper/MaterialPropertyBlockHelper.cs","src_lines":[10,60],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Renderer)"],"addComponentMenu":"Toolkit/Material Property Block Helper"},"src_typeComment":"Wraps MaterialPropertyBlock so you can tweak a renderer's color/float/texture properties at runtime without instancing a new Material (which leaks memory if not manually cleaned up, and breaks batching). Drop on any Renderer and call SetColor/SetFloat/SetTexture — the block is applied automatically.","src_serialized":[],"src_members":[{"id":"SetColor(string, Color)","sig":"public void SetColor(string propertyName, Color color)","kind":"method","name":"SetColor","static":false,"comment":null},{"id":"SetFloat(string, float)","sig":"public void SetFloat(string propertyName, float value)","kind":"method","name":"SetFloat","static":false,"comment":null},{"id":"SetTexture(string, Texture)","sig":"public void SetTexture(string propertyName, Texture texture)","kind":"method","name":"SetTexture","static":false,"comment":null},{"id":"Clear()","sig":"public void Clear()","kind":"method","name":"Clear","static":false,"comment":"Clears all overrides, reverting to the renderer's shared material values."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["GameplayArena_Demo"],"entryKind":"tool","status":"published","summary":"Change a renderer's colour or float at runtime without instancing a material.","overview":["Wraps MaterialPropertyBlock so you can tweak a renderer's properties at runtime without creating a new Material — which leaks unless cleaned up manually, and breaks batching. Drop it on any Renderer and set properties; the block is applied for you."],"useCases":["Tinting each enemy in a crowd differently from one material.","A damage flash that does not instance a material per hit.","Per-instance variation without an asset per variant."],"gotchas":[{"title":"It changes this renderer only","body":"That is the point, and it means it is not a way to change the material for everything sharing it."},{"title":"It initialises lazily, because Awake is not reliable outside Play mode","body":"It uses the toolkit's EnsureInitialized pattern so it works from an editor script or a self-test too."}],"seeAlso":["HighlightToggle","WaterInstanceOverrides"],"src_uses":["FakeLight"],"src_usedBy":["FakeLight","FakeLightInfluenceMode","FakeLightType"],"src_extensionPoints":[]}],"groups":[{"title":"Lighting","ids":["fake-light","ui-fake-light","scene-light-ui-hook","ui-lighting-effect"]},{"title":"Water","ids":["ripple-emitter","planar-reflection","water-depth-texture-enabler","water-instance-overrides","water-pour-visual"]},{"title":"UI Effects","ids":["ui-edge-glow","ui-blur-source","ui-ripple-effect"]},{"title":"Object Effects","ids":["dissolve-effect","force-field-effect","glitch-effect","hologram-effect","highlight-toggle","weapon-trail"]},{"title":"Decals & Surfaces","ids":["decals","grass-bend-emitter"]},{"title":"Post-processing & Plumbing","ids":["speed-radial-blur","material-property-block-helper"]}]};
